// Optional user theme: ~/.config/GoobMessages/theme.css (e.g. generated by matugen) overrides the color variables in
// style.css. It is injected after style.css so it wins, and replaced live when the Go side sees the file change.
import { api, on } from './api.js'

function apply(css) {
  let el = document.getElementById('user-theme')
  if (!css) { el?.remove(); return }
  if (!el) {
    el = document.createElement('style')
    el.id = 'user-theme'
    document.head.appendChild(el)
  }
  el.textContent = css
}

export async function initTheme() {
  on('theme', apply)
  try { apply(await api.userThemeCSS()) } catch {}
}
